    // Helper: check if 以上皆無 checkbox has class "on" in the rendered HTML
    private static bool NoneOfAboveIsOn(string html)
    {
        // <span class="cb on"></span>以上皆無  or  <span class="cb "></span>以上皆無
        var m = Regex.Match(html, @"<span class=""cb ([^""]*)""></span>以上皆無");
        return m.Success && m.Groups[1].Value.Contains("on");
    }

    // Helper: check if a specific disease checkbox has class "on"
    private static bool DiseaseIsOn(string html, string disease)
    {
        var pattern = @"<span class=""cb ([^""]*)""></span>" + Regex.Escape(disease);
        var m = Regex.Match(html, pattern);
        return m.Success && m.Groups[1].Value.Contains("on");
    }

