    [Fact(DisplayName = "R7 / 後端 PetService 不對 MedicalHistory 內容組合執行額外驗證")]
    public async Task PetService_does_not_validate_medical_history_combinations()
    {
        var connection = new SqliteConnection("DataSource=:memory:");
        connection.Open();
        var options = new DbContextOptionsBuilder<PetSalonDbContext>()
            .UseSqlite(connection)
            .Options;
        await using var db = new PetSalonDbContext(options);
        db.Database.EnsureCreated();

        var ids = new SequentialIdGenerator();
        var clock = new FakeClock();
        var ownerSvc = new OwnerService(db, ids, clock);
        var petSvc = new PetService(db, ids, clock);

        var owner = await ownerSvc.CreateAsync(new OwnerInput
        {
            Name = "王小明", NationalId = "A123456789", Phone = "0912345678", Address = "桃園市桃園區慈文路322巷5號"
        });

        // Given Pet.MedicalHistory = ["以上皆無", "心臟病"]（語意衝突但合法字串）
        var input = new PetInput
        {
            OwnerId = owner.OwnerId, Name = "小白", Species = "犬", Breed = "柴犬", Gender = "公", Age = "3 歲",
            Personality = new List<string> { "親人" },
            MedicalHistory = new List<string> { "以上皆無", "心臟病" },
            PhysicalExamination = new PhysicalExamination(),
        };

        // When 呼叫 PetService.CreateAsync
        var pet = await petSvc.CreateAsync(input);

        // Then 不應拋例外；MedicalHistory 儲存兩個值
        pet.MedicalHistory.Should().Contain("以上皆無");
        pet.MedicalHistory.Should().Contain("心臟病");

        await connection.CloseAsync();
        connection.Dispose();
    }

