    [Fact(DisplayName = "R7 / MedicalHistory 包含「以上皆無」時 HTML 勾選「以上皆無」")]
    public void Html_checks_none_of_above_when_list_contains_it()
    {
        var data = SampleData(new List<string> { "以上皆無" });
        var renderer = new ContractTemplateRenderer(_templatePath, _fontPath);
