    [Fact(DisplayName = "R7 / MedicalHistory 包含具體病史時 HTML 不勾選「以上皆無」")]
    public void Html_does_not_check_none_of_above_when_specific_diseases_present()
    {
        var data = SampleData(new List<string> { "心臟病", "氣喘" });
        var renderer = new ContractTemplateRenderer(_templatePath, _fontPath);
        var html = renderer.Render(data);

        DiseaseIsOn(html, "心臟病").Should().BeTrue("心臟病應勾選");
        DiseaseIsOn(html, "氣喘").Should().BeTrue("氣喘應勾選");
        NoneOfAboveIsOn(html).Should().BeFalse("有具體病史時以上皆無不應勾選");
    }

    [Fact(DisplayName = "R7 / 既有 SQLite 中 MedicalHistory=[] 之 Pet 不需 migration 且 PDF 自動勾選")]
    public async Task Existing_pets_with_empty_medical_history_do_not_need_migration()
    {
        var connection = new SqliteConnection("DataSource=:memory:");
        connection.Open();
        var options = new DbContextOptionsBuilder<PetSalonDbContext>()
            .UseSqlite(connection)
            .Options;
        await using var db = new PetSalonDbContext(options);
        db.Database.EnsureCreated();

        var ids = new SequentialIdGenerator();
        var clock = new FakeClock();
        var ownerSvc = new OwnerService(db, ids, clock);
        var petSvc = new PetService(db, ids, clock);

        var owner = await ownerSvc.CreateAsync(new OwnerInput
        {
            Name = "王小明", NationalId = "A123456789", Phone = "0912345678", Address = "桃園市桃園區慈文路322巷5號"
        });

        // 建立 MedicalHistory=[] 的 Pet
        var input = new PetInput
        {
            OwnerId = owner.OwnerId, Name = "小白", Species = "犬", Breed = "柴犬", Gender = "公", Age = "3 歲",
            Personality = new List<string> { "親人" },
            MedicalHistory = new List<string>(),
            PhysicalExamination = new PhysicalExamination(),
        };
        var pet = await petSvc.CreateAsync(input);

        // 重新載入
        var loaded = await petSvc.GetByIdAsync(pet.PetId);
        loaded.MedicalHistory.Should().BeEmpty("MedicalHistory 應為空 List<string>");

        // 後續 PDF 渲染時「以上皆無」應自動勾選
        var appt = new Appointment { AppointmentId = "appt_r7b", OwnerId = owner.OwnerId, PetId = loaded.PetId, Date = new DateOnly(2026, 5, 16), Time = new TimeOnly(10, 0) };
        var rec = new GroomingRecord { GroomingRecordId = "rec_r7b", AppointmentId = appt.AppointmentId, ServiceDate = appt.Date, ServiceTime = appt.Time, MedicalHistory = new List<string>() };
        var renderData = new ContractRenderData(owner, loaded, appt, rec, Array.Empty<byte>(), "安欣動物醫院", "03-3367775", "桃園市桃園區中福街60號");

        var infraOutput = Path.GetDirectoryName(typeof(PuppeteerSharpContractGenerator).Assembly.Location)!;
        var templatePath = Path.Combine(infraOutput, "Pdf", "Templates", "contract.hbs");
        var fontPath = Path.Combine(infraOutput, "Pdf", "Assets", "kaiu.ttf");
        var renderer = new ContractTemplateRenderer(templatePath, fontPath);
        var html = renderer.Render(renderData);

        NoneOfAboveIsOn(html).Should().BeTrue("MedicalHistory=[] → PDF 以上皆無應勾選");

        await connection.CloseAsync();
        connection.Dispose();
    }

